.sec_insert_date as transdate ,cast( -1* isnull(sum(ibd_qty * (ibd_pharm_price+ibd_tax_price)),0)  as decimal(18,3)) [TransValue] ,'مرتجع شراء عام'  , ibh_notes TransNotes , ph.sec_insert_uid UserId FROM item_back_h ph  join item_back_d pd on ibh_id =ibd_ibh_id  join item_catalog ic on ic.itm_id=ibd_itm_id  group by ibh_ven_id ,ph.sec_insert_date ,ibd_ibh_id ,ibh_id, ibh_notes , ph.sec_insert_uid union all  select 4 Tr,fh_from_id as VenId ,fh_id BillID ,sec_insert_date as TransDate, isnull(sum(fh_value),0) TransValue , 'توريد نقديه' TransType  , fh_notes TransNotes , null UserId from f_transaction_header   where fh_from_type=2 and fh_trans_type=1   group by fh_from_id, fh_id,fh_trans_type, sec_insert_date ,fh_trans_type ,fh_notes union all  select 5 Tr,fh_to_id as VenId ,fh_id as BillID , sec_insert_date as billdate,-1*fh_value TransValue ,'صرف نقديه' TransType  ,fh_notes TransNotes ,h.sec_insert_uid UserId FROM f_transaction_header h   where fh_to_type=2 and fh_trans_type=1 union all  select 6 Tr,fh_from_id VenId,h.fh_id BillID,h.sec_insert_date transdate  ,fh_value TransValue, 'استلام ورقه مالية' TransType  ,fh_notes TransNotes ,h.sec_insert_uid UserId FROM f_transaction_header h join f_transaction_header_ext on f_transaction_header_ext.fh_id=h.fh_id  union all  select 7 Tr,fh_from_id as VenId ,h.fh_id AS BillID, f_transaction_header_ext.sec_update_date as transdate  ,-1* fh_value TransValue , 'الغاء ورقه ماليه مستلمه' TransType  ,fh_notes TransNotes ,h.sec_insert_uid UserId from f_transaction_header h join f_transaction_header_ext on f_transaction_header_ext.fh_id=h.fh_id  union all  select 8 Tr,fh_to_id VenId ,h.fh_id AS BillID,h.sec_insert_date transdate , -1*fh_value TransValue  , 'صرف ورقة مالية' TransType  ,fh_notes TransNotes ,h.sec_insert_uid UserId from f_transaction_header h join f_transaction_header_ext on f_transaction_header_ext.fh_id=h.fh_id   WHERE fh_to_type=2 and fh_trans_type=2 and fhe_start=0    union all  select 9 Tr,fh_to_id VenId,h.fh_id BillID ,f_transaction_header_ext.sec_update_date transdate  ,fh_value TransValue ,'الغاء ورقه ماليه صادره' TransType  ,fh_notes TransNotes ,h.sec_insert_uid UserId from f_transaction_header h  join f_transaction_header_ext on f_transaction_header_ext.fh_id=h.fh_id  WHERE fh_to_type=2 and fh_trans_type=2 and fhe_start=0 and fhe_paper_status ='2'   union all  SELECT 10 Tr, fn_who_id as VenId ,fn_id as BillId ,sec_insert_date Transdate ,fn_value TransVal ,'إشعار إضافة' as TransType  ,fn_notes TransNotes , sec_insert_uid UserId FROM F_Notices  where fn_type=1 and fn_who_type=1 union all  SELECT 11 Tr, fn_who_id as VenId , fn_id as BillId , sec_insert_date as datebill  ,-1*fn_value Debit,'إشعار خصم' TransType  ,fn_notes TransNotes , sec_insert_uid UserId FROM F_Notices where fn_type=2 and fn_who_type=1 and fn_notes<>'تعديل خصومات فواتير شراء'
